<?php namespace App\Http\Controllers; use App\Models\{Customer,Supplier}; use Illuminate\Http\Request; class PartyController { public function customers(Request $r){$list=Customer::when($r->search,fn($q)=>$q->where('name','like','%'.$r->search.'%')->orWhere('phone','like','%'.$r->search.'%'))->latest()->paginate(15);return view('parties.customers',compact('list'));} public function storeCustomer(Request $r){$d=$r->validate(['name'=>'required','phone'=>'nullable','address'=>'nullable','type'=>'required','notes'=>'nullable']);Customer::create($d+['code'=>'CUS-'.str_pad((string)(Customer::count()+1),4,'0',STR_PAD_LEFT)]);return back()->with('success','Customer saved.');} public function suppliers(Request $r){$list=Supplier::when($r->search,fn($q)=>$q->where('name','like','%'.$r->search.'%')->orWhere('phone','like','%'.$r->search.'%'))->latest()->paginate(15);return view('parties.suppliers',compact('list'));} public function storeSupplier(Request $r){$d=$r->validate(['name'=>'required','phone'=>'nullable','address'=>'nullable','contact_person'=>'nullable','notes'=>'nullable']);Supplier::create($d+['code'=>'SUP-'.str_pad((string)(Supplier::count()+1),4,'0',STR_PAD_LEFT),'status'=>1]);return back()->with('success','Supplier saved.');} }
